SELECT 

FROM assessment_indicator
WHERE is_active = #{isActive}

    AND parent_id = #{parentId}


    AND (parent_id IS NULL OR parent_id = 0)

ORDER BY sort_order ASC, id ASC

WITH RECURSIVE indicator_tree AS ( -- 查询根指标 SELECT FROM assessment_indicator WHERE id = #{indicatorId}
UNION ALL
-- 递归查询子指标 SELECT ai. FROM assessment_indicator ai INNER JOIN indicator_tree it ON ai.parent_id = it.id ) SELECT * FROM indicator_tree ORDER BY CASE WHEN parent_id IS NULL OR parent_id = 0 THEN id ELSE parent_id END, parent_id ASC, sort_order ASC, id ASC

SELECT COALESCE(SUM(weight), 0)
FROM assessment_indicator
WHERE is_active = 1

    AND parent_id = #{parentId}


    AND (parent_id IS NULL OR parent_id = 0)


    AND id != #{excludeId}

SELECT COALESCE(MAX(sort_order), 0) FROM assessment_indicator WHERE 1=1
AND parent_id = #{parentId}
AND (parent_id IS NULL OR parent_id = 0)

SELECT COUNT(*)
FROM assessment_indicator
WHERE indicator_code = #{indicatorCode}

    AND id != #{excludeId}

