UPDATE assessment_indicator 
SET sort_order = #{item.sortOrder}, update_time = NOW()
WHERE id = #{item.id}

mapper.update:
UPDATE assessment_indicator 
SET is_active = 0, update_time = NOW(), update_by = #{updateBy}
WHERE id IN (
    WITH RECURSIVE indicator_tree AS (
        SELECT id FROM assessment_indicator WHERE id = #{indicatorId}
        UNION ALL
        SELECT ai.id FROM assessment_indicator ai
        INNER JOIN indicator_tree it ON ai.parent_id = it.id
    )
    SELECT id FROM indicator_tree
)
